/// Declares a component whose state lives in `#[state]` fields, like
/// SwiftUI's `@State`.
///
/// The `#[state]` fields are removed from the struct, so a parent builds the
/// component from its props alone. They become a generated `<Name>State`
/// struct (current values) and `<Name>Set` struct (a binding per field, like
/// SwiftUI's `$field`), and the macro implements [`StatefulComponent`].
/// You write an inherent `body` that receives both:
///
/// ```no_run
/// use rui::*;
///
/// #[component]
/// #[derive(Clone)]
/// struct Counter {
///     step: i32,
///     #[state = 0]
///     count: i32,
///     #[state = self.step > 1] // initial values can read props
///     fast: bool,
/// }
///
/// impl Counter {
///     fn body(self, state: CounterState, set: CounterSet) -> impl View {
///         vstack((
///             button(format!("count: {}", state.count), move |cx| {
///                 cx[set.count] += self.step
///             }),
///             toggle(set.fast),
///         ))
///     }
/// }
///
/// vstack((Counter { step: 1 }, Counter { step: 10 })).run();
/// ```
///
/// `#[state]` with no value starts from `Default::default()`. State is kept
/// per position in the view tree and survives re-renders and prop changes.
pub use rui_macros::component;

